//! Stored profiles, declaration occurrences, and exact currency summaries.

use bigdecimal::BigDecimal;
use chrono::{DateTime, Utc};

use super::{
    funder::{Funder, FunderId},
    parliament_member::MemberId,
};

/// Latest stored member profile, not membership at the time of a payment.
#[derive(Clone, Debug)]
pub struct MemberProfile {
    /// Parliament identity.
    pub id: MemberId,
    /// Source name.
    pub name: String,
    /// Latest recorded party identity.
    pub party_id: i32,
    /// Latest recorded party name.
    pub party_name: String,
    /// Latest membership description, including constituencies and Lords memberships.
    pub membership_from: String,
    /// Current Commons membership.
    pub is_current_commons: bool,
}

/// A named funder on a declaration.
#[derive(Clone, Debug)]
pub struct FunderReference {
    /// Persistent identity.
    pub id: FunderId,
    /// Exact source name.
    pub name: String,
}

/// One source funding occurrence, including incomplete values.
#[derive(Clone, Debug)]
pub struct DeclaredFunding {
    /// Named funder when available.
    pub funder: Option<FunderReference>,
    /// Exact source amount.
    pub amount: Option<BigDecimal>,
    /// Normalized source currency, absent when unknown.
    pub currency: Option<String>,
    /// Source payment classification.
    pub payment_type: Option<String>,
}

/// A declaration with all of its funding occurrences.
#[derive(Clone, Debug)]
pub struct MemberDeclaration {
    /// Parliament declaration identity.
    pub source_id: i32,
    /// Canonical source category classification.
    pub category: DeclarationCategory,
    /// Source category.
    pub category_name: String,
    /// Registration date when available.
    pub registered_at: Option<DateTime<Utc>>,
    /// Funding occurrences, preserving duplicates.
    pub entries: Vec<DeclaredFunding>,
}

/// Canonical classification preserves unrecognized source categories.
#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
pub enum DeclarationCategory {
    /// Donations and other support, including loans.
    DonationSupport,
    /// Any other category, retaining its source identity.
    Other(i32),
}
impl DeclarationCategory {
    /// Decodes the source vocabulary without guessing from labels.
    #[must_use]
    pub const fn from_source_id(id: i32) -> Self {
        match id {
            3 => Self::DonationSupport,
            other => Self::Other(other),
        }
    }
    /// Whether the category records donations and other support.
    #[must_use]
    pub const fn is_donation_support(self) -> bool {
        match self {
            Self::DonationSupport => true,
            Self::Other(_) => false,
        }
    }
    /// Encodes the original source identity.
    #[must_use]
    pub const fn source_id(self) -> i32 {
        match self {
            Self::DonationSupport => 3,
            Self::Other(id) => id,
        }
    }
}

/// Complete consistent repository input.
#[derive(Clone, Debug)]
pub struct MemberHistory {
    /// Latest member profile.
    pub member: MemberProfile,
    /// All declarations in registration order.
    pub declarations: Vec<MemberDeclaration>,
}

/// Exact amounts and coverage for one category and currency.
#[derive(Clone, Debug)]
pub struct CategoryTotal {
    /// Source identity.
    pub category: DeclarationCategory,
    /// Original category label.
    pub category_name: String,
    /// Known amounts, unavailable when no amount is known.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: usize,
    /// Occurrences without an amount.
    pub unknown_amount_count: usize,
}

/// Independent amounts for a known currency.
#[derive(Clone, Debug)]
pub struct MemberCurrencyTotal {
    /// Normalized source currency.
    pub currency: String,
    /// Exact total, including zero and negative amounts.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: usize,
    /// Occurrences without an amount.
    pub unknown_amount_count: usize,
    /// All represented categories.
    pub categories: Vec<CategoryTotal>,
}

/// Coverage and exact totals across complete stored history.
#[derive(Clone, Debug)]
pub struct MemberSummary {
    /// Separate currencies without conversion.
    pub currencies: Vec<MemberCurrencyTotal>,
    /// All funding occurrences.
    pub entry_count: usize,
    /// Occurrences whose currency is unknown.
    pub unknown_currency_count: usize,
    /// Earliest known registration timestamp.
    pub first_registered_at: Option<DateTime<Utc>>,
    /// Latest known registration timestamp.
    pub last_registered_at: Option<DateTime<Utc>>,
    /// Declarations without a registration timestamp.
    pub undated_declaration_count: usize,
}

/// Member summary and complete history from one consistent read.
#[derive(Clone, Debug)]
pub struct MemberDetails {
    /// Latest profile.
    pub member: MemberProfile,
    /// Complete ordered declarations.
    pub declarations: Vec<MemberDeclaration>,
    /// Exact complete-history totals.
    pub summary: MemberSummary,
}

/// Canonical funder profile with recorded names.
#[derive(Clone, Debug)]
pub struct FunderProfile {
    /// Persistent funder.
    pub funder: Funder,
    /// Company identifier with leading zeros intact.
    pub company_number: Option<String>,
    /// Every stored exact name, in stable order.
    pub aliases: Vec<String>,
    /// Source funders connected by recorded names, in stable order.
    pub member_ids: Vec<FunderId>,
    /// Direct shared-name evidence, without inferred transitive edges.
    pub alias_links: Vec<FunderAliasLink>,
    /// Reviewed organization-family connections, separate from shared names.
    pub family_links: Vec<FunderFamilyLink>,
}

/// Reviewed family membership connecting two source funders.
#[derive(Clone, Debug)]
pub struct FunderFamilyLink {
    /// First source funder.
    pub left_funder_id: FunderId,
    /// Second source funder.
    pub right_funder_id: FunderId,
    /// Persistent reviewed family key.
    pub family_key: String,
    /// Exact canonical name of the first source funder.
    pub left_name: String,
    /// Exact canonical name of the second source funder.
    pub right_name: String,
}

/// Exact recorded names responsible for a direct connection.
#[derive(Clone, Debug)]
pub struct FunderAliasLink {
    /// First source funder.
    pub left_funder_id: FunderId,
    /// Second source funder.
    pub right_funder_id: FunderId,
    /// Shared name after case and whitespace normalization.
    pub normalized_alias: String,
    /// Exact name recorded for the first funder.
    pub left_alias: String,
    /// Exact name recorded for the second funder.
    pub right_alias: String,
}

/// Compact repository aggregate for one recipient and currency.
#[derive(Clone, Debug)]
pub struct RecipientAllocation {
    /// Latest stored recipient profile.
    pub member: MemberProfile,
    /// Source currency when recorded; unknown currencies never have totals.
    pub currency: Option<String>,
    /// Sum of known amounts, or unavailable if none are known.
    pub known_total: Option<BigDecimal>,
    /// All source occurrences.
    pub entry_count: i64,
    /// Occurrences with missing amounts.
    pub unknown_amount_count: i64,
}

/// Recipient and source declaration containing only this funder's occurrences.
#[derive(Clone, Debug)]
pub struct FunderDeclaration {
    /// Latest recorded recipient profile.
    pub member: MemberProfile,
    /// Source declaration with matching occurrences, preserving duplicates.
    pub declaration: MemberDeclaration,
}

/// Repository input for a consistent funder summary and history.
#[derive(Clone, Debug)]
pub struct FunderFunding {
    /// Persistent funder identity.
    pub profile: FunderProfile,
    /// Source declarations in registration order.
    pub declarations: Vec<FunderDeclaration>,
}

/// Support grouped by recipients' latest stored party.
#[derive(Clone, Debug)]
pub struct PartyTotal {
    /// Latest stored party identity.
    pub party_id: i32,
    /// Latest stored party name.
    pub party_name: String,
    /// Total of known amounts only.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: i64,
    /// Occurrences with unknown amounts.
    pub unknown_amount_count: i64,
}

/// Independent totals and rankings for a single currency.
#[derive(Clone, Debug)]
pub struct CurrencyBreakdown {
    /// Exact complete-history total before recipient ranking.
    pub amount: Option<BigDecimal>,
    /// Source currency.
    pub currency: String,
    /// All recorded party totals.
    pub parties: Vec<PartyTotal>,
    /// Highest known totals, followed by unavailable totals if space remains.
    pub top_recipients: Vec<RecipientAllocation>,
}

/// Funder summary without currency conversion or historical party inference.
#[derive(Clone, Debug)]
pub struct FunderDetails {
    /// Complete source history with matching funding occurrences only.
    pub declarations: Vec<FunderDeclaration>,
    /// Persistent funder identity.
    pub profile: FunderProfile,
    /// Summaries for each known currency.
    pub currencies: Vec<CurrencyBreakdown>,
    /// All funding occurrences.
    pub entry_count: i64,
    /// Occurrences excluded because currency is unknown.
    pub unknown_currency_count: i64,
    /// Maximum recipients per currency.
    pub recipient_limit: usize,
}
//! Entity profiles and summaries from a shared exact aggregate.

mod interface;
pub use interface::EntityDetailsService;

use crate::domain::{
    models::{
        entity_details::{
            CategoryTotal, CurrencyBreakdown, DeclarationCategory, FunderDetails, FunderFunding,
            MemberCurrencyTotal, MemberDetails, MemberHistory, MemberSummary, PartyTotal,
            RecipientAllocation,
        },
        funder::FunderId,
        parliament_member::MemberId,
    },
    repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
};
use std::{cmp::Ordering, collections::BTreeMap};
use thiserror::Error;

const TOP_RECIPIENTS: usize = 10;

/// Entity detail lookup failure.
#[derive(Debug, Error)]
pub enum EntityDetailsError {
    /// No stored identity matches the request.
    #[error("entity not found")]
    NotFound,
    /// Private database diagnostics.
    #[error(transparent)]
    Unexpected(#[from] EntityDetailsRepoError),
}

/// Detail service owns summary rules and presentation limits.
#[derive(Clone)]
pub struct Service<R> {
    repo: R,
}

impl<R> Service<R> {
    /// Creates a detail service.
    #[must_use]
    pub const fn new(repo: R) -> Self {
        Self { repo }
    }
}

impl<R: EntityDetailsRepo> EntityDetailsService for Service<R> {
    async fn member(&self, id: MemberId) -> Result<MemberDetails, EntityDetailsError> {
        self.repo
            .member(id)
            .await?
            .map(summarize_member)
            .ok_or(EntityDetailsError::NotFound)
    }
    async fn funder(&self, id: FunderId) -> Result<FunderDetails, EntityDetailsError> {
        self.repo
            .funder_funding(id)
            .await?
            .map(summarize_funder)
            .ok_or(EntityDetailsError::NotFound)
    }
}

fn add_known(total: &mut Option<bigdecimal::BigDecimal>, amount: Option<&bigdecimal::BigDecimal>) {
    if let Some(amount) = amount {
        match total {
            Some(total) => *total += amount,
            None => *total = Some(amount.clone()),
        }
    }
}

fn summarize_member(history: MemberHistory) -> MemberDetails {
    let mut currencies: BTreeMap<String, MemberCurrencyTotal> = BTreeMap::new();
    let mut categories: BTreeMap<(String, DeclarationCategory, String), CategoryTotal> =
        BTreeMap::new();
    let mut summary = MemberSummary {
        currencies: Vec::new(),
        entry_count: 0,
        unknown_currency_count: 0,
        first_registered_at: None,
        last_registered_at: None,
        undated_declaration_count: 0,
    };
    for declaration in &history.declarations {
        if let Some(date) = declaration.registered_at {
            summary.first_registered_at = Some(
                summary
                    .first_registered_at
                    .map_or(date, |first| first.min(date)),
            );
            summary.last_registered_at = Some(
                summary
                    .last_registered_at
                    .map_or(date, |last| last.max(date)),
            );
        } else {
            summary.undated_declaration_count += 1;
        }
        for entry in &declaration.entries {
            summary.entry_count += 1;
            let Some(currency) = &entry.currency else {
                summary.unknown_currency_count += 1;
                continue;
            };
            let group = currencies
                .entry(currency.clone())
                .or_insert_with(|| MemberCurrencyTotal {
                    currency: currency.clone(),
                    amount: None,
                    entry_count: 0,
                    unknown_amount_count: 0,
                    categories: Vec::new(),
                });
            add_known(&mut group.amount, entry.amount.as_ref());
            group.entry_count += 1;
            group.unknown_amount_count += usize::from(entry.amount.is_none());
            let category = categories
                .entry((
                    currency.clone(),
                    declaration.category,
                    declaration.category_name.clone(),
                ))
                .or_insert_with(|| CategoryTotal {
                    category: declaration.category,
                    category_name: declaration.category_name.clone(),
                    amount: None,
                    entry_count: 0,
                    unknown_amount_count: 0,
                });
            add_known(&mut category.amount, entry.amount.as_ref());
            category.entry_count += 1;
            category.unknown_amount_count += usize::from(entry.amount.is_none());
        }
    }
    for ((currency, _, _), category) in categories {
        if let Some(group) = currencies.get_mut(&currency) {
            group.categories.push(category);
        }
    }
    summary.currencies = currencies.into_values().collect();
    MemberDetails {
        member: history.member,
        declarations: history.declarations,
        summary,
    }
}

fn compare_allocations(left: &RecipientAllocation, right: &RecipientAllocation) -> Ordering {
    right
        .known_total
        .cmp(&left.known_total)
        .then_with(|| left.member.id.value().cmp(&right.member.id.value()))
        .then_with(|| left.member.name.cmp(&right.member.name))
}

fn summarize_funder(funding: FunderFunding) -> FunderDetails {
    let mut entry_count = 0;
    let mut unknown_currency_count = 0;
    let mut currencies: BTreeMap<String, Vec<RecipientAllocation>> = BTreeMap::new();
    let mut recipients: BTreeMap<(String, u32), RecipientAllocation> = BTreeMap::new();
    for source in &funding.declarations {
        for entry in &source.declaration.entries {
            entry_count += 1;
            let Some(currency) = &entry.currency else {
                unknown_currency_count += 1;
                continue;
            };
            let allocation = recipients
                .entry((currency.clone(), source.member.id.value()))
                .or_insert_with(|| RecipientAllocation {
                    member: source.member.clone(),
                    currency: Some(currency.clone()),
                    known_total: None,
                    entry_count: 0,
                    unknown_amount_count: 0,
                });
            add_known(&mut allocation.known_total, entry.amount.as_ref());
            allocation.entry_count += 1;
            allocation.unknown_amount_count += i64::from(entry.amount.is_none());
        }
    }
    for ((currency, _), allocation) in recipients {
        currencies.entry(currency).or_default().push(allocation);
    }
    let currencies = currencies
        .into_iter()
        .map(|(currency, mut allocations)| {
            let mut amount = None;
            let mut parties: BTreeMap<(i32, String), PartyTotal> = BTreeMap::new();
            for allocation in &allocations {
                add_known(&mut amount, allocation.known_total.as_ref());
                let party = parties
                    .entry((
                        allocation.member.party_id,
                        allocation.member.party_name.clone(),
                    ))
                    .or_insert_with(|| PartyTotal {
                        party_id: allocation.member.party_id,
                        party_name: allocation.member.party_name.clone(),
                        amount: None,
                        entry_count: 0,
                        unknown_amount_count: 0,
                    });
                if let Some(amount) = &allocation.known_total {
                    if let Some(total) = &mut party.amount {
                        *total += amount;
                    } else {
                        party.amount = Some(amount.clone());
                    }
                }
                party.entry_count += allocation.entry_count;
                party.unknown_amount_count += allocation.unknown_amount_count;
            }
            let mut parties: Vec<_> = parties.into_values().collect();
            parties.sort_by(|left, right| {
                right
                    .amount
                    .cmp(&left.amount)
                    .then_with(|| left.party_name.cmp(&right.party_name))
                    .then_with(|| left.party_id.cmp(&right.party_id))
            });
            allocations.sort_by(compare_allocations);
            allocations.truncate(TOP_RECIPIENTS);
            CurrencyBreakdown {
                amount,
                currency,
                parties,
                top_recipients: allocations,
            }
        })
        .collect();
    FunderDetails {
        declarations: funding.declarations,
        profile: funding.profile,
        currencies,
        entry_count,
        unknown_currency_count,
        recipient_limit: TOP_RECIPIENTS,
    }
}
